mapper.select:
SELECT fa.id AS audit_id, f.id AS farm_id, f.name AS farm_name, u.name AS owner_name, u.phone AS owner_phone, c.name AS category_name, f.scale AS scale, CASE c.count_unit WHEN 'HEAD' THEN '头' WHEN 'BIRD' THEN '只' ELSE c.count_unit END AS count_unit_text, CONCAT(f.province, ' · ', f.district) AS region_text, COALESCE(JSON_LENGTH(fa.snapshot_json, '$.qualificationFileIds'), 0) AS image_count, fa.submit_no AS submit_no, fa.submitted_at AS submitted_at, fa.status AS status, a.name AS auditor_name, fa.audited_at AS audited_at, fa.audit_opinion AS audit_opinion, fa.reject_reason AS reject_reason FROM t_farm_audit fa JOIN t_farm f ON f.id = fa.farm_id AND f.deleted = 0 JOIN t_user u ON u.id = f.owner_user_id LEFT JOIN t_category c ON c.id = f.main_category_id LEFT JOIN t_admin a ON a.id = fa.audited_by
ORDER BY fa.submitted_at ASC, fa.id ASC ORDER BY fa.audited_at DESC, fa.id DESC
LIMIT #{offset}, #{limit}

mapper.sql:
WHERE fa.status = 'PENDING'
  AND fa.submitted_at < #{overdueBefore}
  AND f.deleted = 0

    AND (f.name LIKE CONCAT('%', #{keyword}, '%')
         OR u.name LIKE CONCAT('%', #{keyword}, '%')
         OR (#{keyword} REGEXP '^[0-9]{11}$' AND u.phone = #{keyword}))

AND f.main_category_id = #{categoryId}
AND LEFT(f.adcode, 2) = #{provincePrefix}
AND fa.submit_no = 1
AND fa.submit_no > 1

mapper.select:
SELECT * FROM t_file
WHERE deleted = 0 AND id IN
#{id}

SELECT fc.id AS change_id, f.id AS farm_id, f.name AS farm_name, u.name AS owner_name, u.phone AS owner_phone, fc.name_changed AS name_changed, fc.address_changed AS address_changed, fc.qual_changed AS qual_changed, fc.remark AS remark, fc.created_at AS submitted_at, fc.status AS status, a.name AS auditor_name, fc.audited_at AS audited_at, fc.audit_opinion AS audit_opinion, fc.reject_reason AS reject_reason FROM t_farm_change fc JOIN t_farm f ON f.id = fc.farm_id AND f.deleted = 0 JOIN t_user u ON u.id = f.owner_user_id LEFT JOIN t_admin a ON a.id = fc.audited_by
ORDER BY fc.created_at ASC, fc.id ASC ORDER BY fc.audited_at DESC, fc.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM t_farm
WHERE owner_user_id = #{ownerUserId}
  AND deleted = 0
  AND id <> #{excludeFarmId}
  AND name = #{name}

SELECT cr.id AS id, cr.request_no AS request_no, cr.biz_type AS biz_type, cr.record_locator AS record_locator, cr.farm_id AS farm_id, f.name AS farm_name, cr.source_module AS source_module, cr.change_type AS change_type, cr.field_name AS field_name, cr.before_display AS before_display, cr.after_display AS after_display, cr.impact_stock AS impact_stock, cr.impact_cost AS impact_cost, cr.impact_inventory AS impact_inventory, cr.impact_sellable_date AS impact_sellable_date, cr.impact_income AS impact_income, cr.impact_stats AS impact_stats, su.name AS submitter_name, cr.submitter_role AS submitter_role, cr.submitted_at AS submitted_at, cr.status AS status, a.name AS reviewer_name, cr.reviewed_at AS reviewed_at FROM t_change_request cr JOIN t_farm f ON f.id = cr.farm_id AND f.deleted = 0 JOIN t_user su ON su.id = cr.submitted_by LEFT JOIN t_batch b ON b.id = cr.batch_id LEFT JOIN t_admin a ON a.id = cr.reviewed_by
ORDER BY cr.submitted_at ASC, cr.id ASC ORDER BY cr.reviewed_at DESC, cr.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM t_change_request cr JOIN t_farm f ON f.id = cr.farm_id AND f.deleted = 0 JOIN t_user su ON su.id = cr.submitted_by LEFT JOIN t_batch b ON b.id = cr.batch_id WHERE cr.status = #{status}
AND (f.name LIKE CONCAT('%', #{keyword}, '%') OR su.name LIKE CONCAT('%', #{keyword}, '%') OR b.batch_no = #{keyword} OR cr.record_locator LIKE CONCAT('%', #{keyword}, '%'))
AND cr.source_module = #{sourceModule} AND cr.impact_stock = 1 AND cr.impact_cost = 1 AND cr.impact_inventory = 1 AND cr.impact_sellable_date = 1 AND cr.impact_income = 1 AND cr.impact_stats = 1

SELECT ar.id AS id, ar.user_id AS user_id, u.name AS user_name, ar.old_phone AS old_phone, ar.new_phone AS new_phone, (ar.new_phone_verified_at IS NOT NULL) AS new_phone_verified, ar.code_attempt_no AS code_attempt_no, ar.code_fail_count AS code_fail_count, ar.description AS description, ar.submit_channel AS submit_channel, pa.name AS proxy_admin_name, ar.created_at AS submitted_at, ar.status AS status, a.name AS handled_by_name, ar.handled_at AS handled_at, ar.version AS version FROM t_account_recovery ar JOIN t_user u ON u.id = ar.user_id LEFT JOIN t_admin a ON a.id = ar.handled_by LEFT JOIN t_admin pa ON pa.id = ar.proxy_admin_id
ORDER BY ar.created_at ASC, ar.id ASC ORDER BY ar.handled_at DESC, ar.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM t_account_recovery
WHERE user_id = #{userId}
  AND created_at >= #{since}
  AND id <> #{excludeId}
